SELECT DISTINCT CONCAT(sh.alias_name, '.', sp.alias_name) FROM sys_role_permit rp INNER JOIN sys_permit sp ON sp.id = rp.permit_id AND sp.is_deleted = 0 INNER JOIN sys_handler sh ON sh.id = sp.handler_id AND sh.is_deleted = 0 WHERE rp.role_id IN
#{id}
AND rp.is_deleted = 0 AND sh.alias_name IS NOT NULL AND sh.alias_name <> '' AND sp.alias_name IS NOT NULL AND sp.alias_name <> ''
